import{_ as t,o as n,c as s,ah as r}from"./chunks/framework.DDXs_i7t.js";const f=JSON.parse('{"title":"Sound-Konzept: Folge 1 – Das Flüstern des Goldes","description":"","frontmatter":{},"headers":[],"relativePath":"hoerbuch/sound-konzept-folge-1.md","filePath":"hoerbuch/sound-konzept-folge-1.md"}'),l={name:"hoerbuch/sound-konzept-folge-1.md"};function i(a,e,o,d,g,h){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="sound-konzept-folge-1-–-das-flustern-des-goldes" tabindex="-1">Sound-Konzept: Folge 1 – Das Flüstern des Goldes <a class="header-anchor" href="#sound-konzept-folge-1-–-das-flustern-des-goldes" aria-label="Permalink to &quot;Sound-Konzept: Folge 1 – Das Flüstern des Goldes&quot;">​</a></h1><p>Dieses Dokument dient als akustische Regieanweisung für die Produktion der ersten Hörbuch-Folge. Es definiert die Soundeffekte (SFX), die musikalische Untermalung und die atmosphärischen Layer.</p><hr><h2 id="_1-atmo-layer-grundstimmung" tabindex="-1">1. Atmo-Layer (Grundstimmung) <a class="header-anchor" href="#_1-atmo-layer-grundstimmung" aria-label="Permalink to &quot;1. Atmo-Layer (Grundstimmung)&quot;">​</a></h2><p>Diese Sounds laufen dezent im Hintergrund der jeweiligen Akte:</p><ul><li><strong>Akt 1 (Heidi):</strong> „Rich Lake“ – Sanftes, rhythmisches Plätschern von Wasser gegen einen Schiffsrumpf, entferntes Rufen von Möwen, das leise Summen einer Klimaanlage (High-End-Luxus).</li><li><strong>Akt 2 (Helmut 1936):</strong> „Industrial Grey“ – Ein tiefer, mechanischer Grundton, das ferne Dröhnen von Fabrikschornsteinen, der Hall eines großen, fast leeren Raumes.</li><li><strong>Akt 3 (August W. 2026):</strong> „Fluorescent Stress“ – Das nervöse Summen von Neonröhren, das ferne Gemurmel in einem Gerichtsflur, das Reiben von Stoff auf Leder (Unruhe auf der Anklagebank).</li></ul><hr><h2 id="_2-spezifische-sfx-cues-zeitstempel-basiert" tabindex="-1">2. Spezifische SFX-Cues (Zeitstempel-basiert) <a class="header-anchor" href="#_2-spezifische-sfx-cues-zeitstempel-basiert" aria-label="Permalink to &quot;2. Spezifische SFX-Cues (Zeitstempel-basiert)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Segment</th><th style="text-align:left;">Aktion / Dialogzeile</th><th style="text-align:left;">Sound-Effekt (SFX)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Intro</strong></td><td style="text-align:left;">„Geld schläft nie...“</td><td style="text-align:left;"><strong>Ticken einer Patek Philippe</strong>, das abrupt stoppt. Dann: <strong>Schauer von Goldmünzen</strong> auf Marmorboden.</td></tr><tr><td style="text-align:left;"><strong>Akt 1</strong></td><td style="text-align:left;">„Geräusch einer Perlenkette...“</td><td style="text-align:left;"><strong>Klicken von Perle auf Perle</strong> (extrem nahmikrofoniert), gefolgt vom <strong>Rascheln schwerer Seide</strong>.</td></tr><tr><td style="text-align:left;"><strong>Akt 1</strong></td><td style="text-align:left;">„Rain of Gold“ (Grok)</td><td style="text-align:left;"><strong>Synthetisches Donnerrollen</strong>, das sich in das <strong>Prasseln von Münzen</strong> (wie Regen) verwandelt.</td></tr><tr><td style="text-align:left;"><strong>Akt 2</strong></td><td style="text-align:left;">„Duisburg, 23. April 1936“</td><td style="text-align:left;"><strong>Hartes Klacken von Schreibmaschinentasten</strong>, ein mechanischer <strong>Wagenrücklauf</strong>.</td></tr><tr><td style="text-align:left;"><strong>Akt 2</strong></td><td style="text-align:left;">„Während die Tinte trocknet...“</td><td style="text-align:left;"><strong>Geräusch einer Feder auf Papier</strong>, gefolgt vom <strong>Zuschlagen eines schweren Tresors</strong>.</td></tr><tr><td style="text-align:left;"><strong>Akt 3</strong></td><td style="text-align:left;">„WhatsApp-Benachrichtigungstöne“</td><td style="text-align:left;"><strong>Serienweises Aufploppen</strong> von iOS-Benachrichtigungen (überlappend, erzeugend ein Gefühl der Überforderung).</td></tr><tr><td style="text-align:left;"><strong>Akt 3</strong></td><td style="text-align:left;">„Richtergabel-Schlag“</td><td style="text-align:left;">Ein <strong>dumpfer, hallender Schlag</strong>, der digital verzerrt wird und in den Outro-Beat übergeht.</td></tr></tbody></table><hr><h2 id="_3-musikalische-leitfaden" tabindex="-1">3. Musikalische Leitfäden <a class="header-anchor" href="#_3-musikalische-leitfaden" aria-label="Permalink to &quot;3. Musikalische Leitfäden&quot;">​</a></h2><ul><li><strong>Thema „Das Gold“:</strong> Ein solitäres Cello, sehr tief gestimmt, spielt eine elegante, aber melancholische Melodie in Moll. Es symbolisiert die Last des Reichtums.</li><li><strong>Thema „Die KI“:</strong> Kurze, hochfrequente Glitch-Sounds und minimale Sinus-Töne, die den Übergang zwischen Grok und Gemini markieren.</li><li><strong>Thema „Die Arisierung“:</strong> Ein schleppender, fast militärischer Rhythmus, erzeugt durch das rhythmische Schließen von Archivschubladen.</li></ul><hr><p><em>Konzept erstellt von Gemini CLI für Volti Sodala. Februar 2026.</em></p>',14)])])}const c=t(l,[["render",i]]);export{f as __pageData,c as default};
